class Solution {
  private boolean dfs(char[][] board, int i, int j, String word, int idx) {
    if (idx == word.length()) return true;
    if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] != word.charAt(idx)) {
      return false;
    }
    char tmp = board[i][j];
    board[i][j] = '#';
    boolean found = dfs(board, i + 1, j, word, idx + 1) || dfs(board, i - 1, j, word, idx + 1)
        || dfs(board, i, j + 1, word, idx + 1) || dfs(board, i, j - 1, word, idx + 1);
    board[i][j] = tmp;
    return found;
  }

  public boolean exist(char[][] board, String word) {
    for (int i = 0; i < board.length; i++) {
      for (int j = 0; j < board[0].length; j++) {
        if (dfs(board, i, j, word, 0)) return true;
      }
    }
    return false;
  }
}

class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        rows, cols = len(board), len(board[0])

        def dfs(i: int, j: int, idx: int) -> bool:
            if idx == len(word):
                return True
            if i < 0 or i >= rows or j < 0 or j >= cols or board[i][j] != word[idx]:
                return False
            tmp = board[i][j]
            board[i][j] = "#"
            found = (
                dfs(i + 1, j, idx + 1)
                or dfs(i - 1, j, idx + 1)
                or dfs(i, j + 1, idx + 1)
                or dfs(i, j - 1, idx + 1)
            )
            board[i][j] = tmp
            return found

        for i in range(rows):
            for j in range(cols):
                if dfs(i, j, 0):
                    return True
        return False

impl Solution {
  pub fn exist(mut board: Vec<Vec<char>>, word: String) -> bool {
    let w = word.as_bytes();
    let rows = board.len();
    let cols = board[0].len();
    fn dfs(board: &mut Vec<Vec<char>>, i: i32, j: i32, w: &[u8], idx: usize) -> bool {
      if idx == w.len() {
        return true;
      }
      if i < 0 || i >= board.len() as i32 || j < 0 || j >= board[0].len() as i32 {
        return false;
      }
      let (ui, uj) = (i as usize, j as usize);
      if board[ui][uj] as u8 != w[idx] {
        return false;
      }
      let tmp = board[ui][uj];
      board[ui][uj] = '#';
      let found = dfs(board, i + 1, j, w, idx + 1)
        || dfs(board, i - 1, j, w, idx + 1)
        || dfs(board, i, j + 1, w, idx + 1)
        || dfs(board, i, j - 1, w, idx + 1);
      board[ui][uj] = tmp;
      found
    }
    for i in 0..rows {
      for j in 0..cols {
        if dfs(&mut board, i as i32, j as i32, w, 0) {
          return true;
        }
      }
    }
    false
  }
}

const exist = (board: string[][], word: string): boolean => {
  const rows = board.length;
  const cols = board[0].length;

  const dfs = (i: number, j: number, idx: number): boolean => {
    if (idx === word.length) return true;
    if (i < 0 || i >= rows || j < 0 || j >= cols || board[i][j] !== word[idx]) return false;
    const tmp = board[i][j];
    board[i][j] = '#';
    const found =
      dfs(i + 1, j, idx + 1) ||
      dfs(i - 1, j, idx + 1) ||
      dfs(i, j + 1, idx + 1) ||
      dfs(i, j - 1, idx + 1);
    board[i][j] = tmp;
    return found;
  };

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (dfs(i, j, 0)) return true;
    }
  }
  return false;
};
